Storefront SPA.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(storefront_spa, "Storefront SPA") {
    Component(Router, "Router", "React Router", "Manages client-side routing and view transitions within the single-page application.")
    Component(Catalog_View, "Catalog View", "React Component", "Provides the user interface for browsing books and searching the catalog.")
    Component(Checkout_View, "Checkout View", "React Component", "Handles user interactions for the secure multi-currency checkout process.")
    Component(Review_Recommendation_View, "Review & Recommendation View", "React Component", "Displays book recommendations and user-submitted reviews.")
}

Rel(Router, Catalog_View, "Renders", "")
Rel(Router, Checkout_View, "Renders", "")
Rel(Router, Review_Recommendation_View, "Renders", "")

@enduml

Recommendation & Review Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(recommendation_review_service, "Recommendation & Review Service") {
    Component(Recommendation_Controller, "Recommendation Controller", "FastAPI Router", "Handles incoming HTTP requests for book recommendations and user reviews.")
    Component(Recommendation_Engine, "Recommendation Engine", "Python Machine Learning Library", "Processes user behavior and catalog data to generate personalized book recommendations.")
    Component(Review_Manager, "Review Manager", "Python Service Logic", "Validates, stores, and retrieves book reviews submitted by registered reviewers.")
}

Rel(Recommendation_Controller, Recommendation_Engine, "Invokes recommendation generation algorithms")
Rel(Recommendation_Controller, Review_Manager, "Delegates review CRUD operations")
@enduml

Async Notification Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Async Notification Service container

Container_Boundary(async_notification_service, "Async Notification Service") {
    Component(Queue_Listener, "Queue Listener", "Node.js, AWS SQS Consumer", "Listens to AWS SQS queues for asynchronous event messages from the Order & Checkout Service.")
    Component(Notification_Dispatcher, "Notification Dispatcher", "Node.js/Express", "Processes and dispatches notifications to external notification providers based on received events.")
}

Rel(Queue_Listener, Notification_Dispatcher, "Forwards event messages for processing")

@enduml
